function rpOrdina(G,ord){ var f={ tot:function(a,b){ return b.tot-a.tot; }, n:function(a,b){ return b.n-a.n||b.tot-a.tot; }, media:function(a,b){ return (b.st.media||0)-(a.st.media||0); }, aperto:function(a,b){ return b.aperto-a.aperto||b.tot-a.tot; }, nome:function(a,b){ return a.nome.localeCompare(b.nome,"it"); }, ultimo:function(a,b){ return (b.ultimo||"").localeCompare(a.ultimo||""); } }[ord]||function(a,b){ return b.tot-a.tot; }; return G.slice().sort(f); }
